class Solution {
public:
    long long countNonDecreasingSubarrays(vector<int>& nums, int k) {
        long long ans = 0, cost = 0;
        deque<pair<int, int>> dq;
        int j = nums.size() - 1;

        for (int i = (int)nums.size() - 1; i >= 0; --i) {
            int num = nums[i];
            int count = 1;
            while (!dq.empty() && dq.back().first < num) {
                auto [nxtNum, nxtCount] = dq.back();
                dq.pop_back();
                count += nxtCount;
                cost += (long long)(num - nxtNum) * nxtCount;
            }
            dq.push_back({num, count});

            while (cost > k) {
                auto [rmNum, rmCount] = dq.front();
                dq.pop_front();
                cost -= (long long)(rmNum - nums[j]);
                j--;
                if (rmCount > 1) {
                    dq.push_front({rmNum, rmCount - 1});
                }
            }
            ans += j - i + 1;
        }
        return ans;
    }
};

class Solution {
    public long countNonDecreasingSubarrays(int[] nums, int k) {
        long ans = 0, cost = 0;
        Deque<int[]> dq = new ArrayDeque<>();
        int j = nums.length - 1;

        for (int i = nums.length - 1; i >= 0; --i) {
            int num = nums[i];
            int count = 1;
            while (!dq.isEmpty() && dq.peekLast()[0] < num) {
                int[] nxt = dq.pollLast();
                count += nxt[1];
                cost += (long)(num - nxt[0]) * nxt[1];
            }
            dq.offerLast(new int[]{num, count});

            while (cost > k) {
                int[] rm = dq.pollFirst();
                cost -= (long)(rm[0] - nums[j]);
                j--;
                if (rm[1] > 1) {
                    dq.offerFirst(new int[]{rm[0], rm[1] - 1});
                }
            }
            ans += j - i + 1;
        }
        return ans;
    }
}

var countNonDecreasingSubarrays = function(nums, k) {
    let ans = 0, cost = 0;
    const dq = [];
    let j = nums.length - 1;

    for (let i = nums.length - 1; i >= 0; --i) {
        const num = nums[i];
        let count = 1;
        while (dq.length > 0 && dq[dq.length - 1][0] < num) {
            const [nxtNum, nxtCount] = dq.pop();
            count += nxtCount;
            cost += (num - nxtNum) * nxtCount;
        }
        dq.push([num, count]);

        while (cost > k) {
            const [rmNum, rmCount] = dq[0];
            cost -= (rmNum - nums[j]);
            j--;
            if (rmCount > 1) {
                dq[0][1]--;
            } else {
                dq.shift();
            }
        }
        ans += j - i + 1;
    }
    return ans;
};
